<?php defined('BASEPATH') or exit('No direct script access allowed'); $CI=&get_instance(); $CI->load->model('cabinet_maker/cabinet_maker_model'); $rows=$CI->cabinet_maker_model->get_designs($project->id); ?><div class="panel_s"><div class="panel-body"><div class="tw-flex tw-justify-between"><h4><i class="fa-solid fa-kitchen-set"></i> <?= _l('cabinet_maker'); ?></h4><?php if(cabinet_maker_can('create')){ ?><a href="<?= admin_url('cabinet_maker?project_id='.$project->id); ?>" class="btn btn-primary">New Design</a><?php } ?></div><hr><?php if(!$rows){ ?><div class="alert alert-info">No cabinet design has been created for this project.</div><?php } else { ?><table class="table"><thead><tr><th>Name</th><th>Status</th><th>Total</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $d){ ?><tr><td><a href="<?= admin_url('cabinet_maker/designer/'.$d->id); ?>"><?= html_escape($d->name); ?></a></td><td><?= html_escape($d->status); ?></td><td><?= app_format_money($d->total,get_base_currency()); ?></td><td><?= html_escape($d->date_updated?:$d->date_created); ?></td></tr><?php } ?></tbody></table><?php } ?></div></div>
